package server

import (
	"testing"

	"github.com/nyrda/hyprmasq/mcp/internal/hypr"
)

// TestWording pins the messages that tell a model what happened and what to do next: the hints and the error messages
// that it acts on. The other tests compare results with the constants and builders named here, so that a deliberate
// change of wording is made in this table, where it can be read and reviewed as a whole.
func TestWording(t *testing.T) {
	click := []action{{Kind: "click"}}
	batch := []action{{Kind: "key", Keys: []string{"ctrl", "q"}}, {Kind: "pause"}, {Kind: "type"}, {Kind: "click"}}
	unchangedShot := func(base string) *shotOut { return &shotOut{ID: "s2", Changes: &changesOut{Base: base}} }
	delivered := func(sh *shotOut) *actOut {
		return &actOut{Actions: &actionsOut{Done: 1, Total: 1, Delivery: "complete"}, Wait: &waitOut{Ended: "quiet"}, Shot: sh}
	}
	menuState := hypr.State{X11: &hypr.X11Kind{OverrideRedirect: true}, Source: &hypr.Source{Window: "0xa1", StableID: "1a"}}
	appWindows := []hypr.Window{{Address: "0xa1", StableID: "1a"}}
	for _, c := range []struct{ name, got, want string }{
		{"hintNothingSent", hintNothingSent,
			"Nothing was sent."},
		{"hintWindows", hintWindows,
			"Call windows to find the window again."},
		{"hintScreenshot", hintScreenshot,
			"Take a screenshot and read the coordinates from the new shot."},
		{"hintScreenshotShot", hintScreenshotShot,
			"Read the coordinates from the new shot in this result."},
		{"hintPluginUser", hintPluginUser,
			"Tell the user. hyprmasq cannot work until this is fixed."},
		{"hintUncertain", hintUncertain,
			"The sender lost its connection before the plugin confirmed the input, so any action may or may not have been applied."},
		{"hintCannotType", hintCannotType,
			"Leave the character out, or ask the user how to enter it."},
		{"hintHoldMissing", hintHoldMissing,
			"This window has the user's keyboard or pointer focus, or shares its Wayland connection with the window that has it, so buttons and modifiers cannot stay pressed between input frames. Use the keyboard instead, for example shift and the arrow keys to select, or a click without modifiers."},
		{"hintChordHoldMissing", hintChordHoldMissing,
			"This window has the user's keyboard or pointer focus, or shares its Wayland connection with the window that has it, so of the keys of a chord only modifiers such as ctrl, alt, shift and super stay pressed between input frames, and the others would arrive one after another. Hold only modifiers, or press the keys in separate key actions."},
		{"hintUnreachable", hintUnreachable,
			"Pointer input reaches the window and the area right of and below it. Click the part of the popup that lies over the window, or use the keyboard, for example the arrow keys and enter in a menu."},
		{"hintOutsideRegions", hintOutsideRegions,
			"Pointer input reaches the window and the area right of and below it up to the edges of its monitor; the window may have moved since the shot."},
		{"hintClosedBySent", hintClosedBySent,
			"The window closed while the input was sent, maybe because of it, for example through a quit shortcut or a close button. Call windows to see what is open now."},
		{"hintCaptureFailed", hintCaptureFailed,
			"The input was applied, but the screenshot failed. Take a screenshot before repeating anything."},
		{"hintLateShortcut", hintLateShortcut,
			"This app shares its keyboard focus between this window and the user's, which gets it back about 250 ms after a shortcut or function key, so one that the app handles later may not have run. Use a menu or a button instead, or launch a separate instance of the app with launch."},
		{"after input, with a shot", finalHint(&toolError{Code: "internal"}, delivered(&shotOut{ID: "s2"})),
			"Look at the shot before repeating anything."},
		{"after input, without a shot", finalHint(&toolError{Code: "internal"}, delivered(nil)),
			"Take a screenshot and look at it before repeating anything."},
		{"after input, with a changes shot without change", finalHint(&toolError{Code: "internal"}, delivered(unchangedShot("s1"))),
			"Look at s1 before repeating anything."},
		{"shared focus returned, without a shot", focusReturnedHint(nil),
			"The user's input took this app's shared keyboard focus back from this window shortly after a shortcut or function key of the batch, so it may or may not have taken effect. Take a screenshot and look at it: if it shows the result, go on; if it is unclear, verify the window's state before repeating the action."},
		{"shared focus returned, with a shot", focusReturnedHint(&shotOut{ID: "s2"}),
			"The user's input took this app's shared keyboard focus back from this window shortly after a shortcut or function key of the batch, so it may or may not have taken effect. Look at the shot: if it shows the result, go on; if it is unclear, verify the window's state before repeating the action."},
		{"drag cancelled to protect the user's input", dragHint(&dragOut{Outcome: "cancelled", Reason: "shared_focus"}, nil),
			"The app started a drag-and-drop, which hyprmasq cancelled to protect the user's input: this window shares its app with the window that has the user's keyboard or pointer focus, so the user's input could reach the drag. Nothing was dropped, though the pointer motion was delivered. Do it without dragging, through what the app offers instead, such as cut and paste, a menu, buttons or keyboard commands that move the item, or a mode that drags with plain pointer motion; otherwise ask the user to do the drag."},
		{"drag refused as busy", dragHint(&dragOut{Outcome: "cancelled", Reason: "busy"}, nil),
			"The app started a drag-and-drop, which hyprmasq cancelled to protect the user's input: an earlier drag of the app had not ended, or its drop was still waiting for the app. Nothing was dropped, though the pointer motion was delivered. Do it without dragging, through what the app offers instead, such as cut and paste, a menu, buttons or keyboard commands that move the item, or a mode that drags with plain pointer motion; otherwise ask the user to do the drag."},
		{"drag cancelled by the app", dragHint(&dragOut{Outcome: "cancelled", Private: true, Reason: "rejected"}, nil),
			"The app's drag-and-drop was cancelled, since it ended over a place that took none of its types or actions: nothing was dropped. Take a screenshot and look at it before you drag again, at a place that takes the item."},
		{"drag cancelled by the user's input", dragHint(&dragOut{Outcome: "cancelled", Private: true, Reason: "user_input"}, nil),
			"The app's drag-and-drop was cancelled, since the user's own input reached the app, which ends the drag first: nothing was dropped. Take a screenshot and look at it, and drag again once the user has left the app, or ask the user."},
		{"drop not confirmed in time", dragHint(&dragOut{Outcome: "unconfirmed", Private: true, Reason: "timeout"}, nil),
			"The drag-and-drop dropped, but the app did not confirm it within 10 seconds, so whether it took the item is not known. Take a screenshot and look at it before repeating anything: a repeated move may move the item twice."},
		{"drop not confirmed before the drag ended", dragHint(&dragOut{Outcome: "unconfirmed", Private: true, Reason: "source_gone"}, nil),
			"The drag-and-drop dropped, but it ended before the app confirmed it, since the app ended the drag itself, so whether the app took the item is not known. Take a screenshot and look at it before repeating anything: a repeated move may move the item twice."},
		{"drop pending", dragHint(&dragOut{Outcome: "pending", Phase: "dropped", Private: true}, nil),
			"The drag-and-drop dropped, and the app had not confirmed it by the deadline. Take a screenshot and look at it before repeating anything; to wait for it, act with no actions."},
		{"drag pending", dragHint(&dragOut{Outcome: "pending", Phase: "active", Private: true}, nil),
			"The drag-and-drop had not dropped by the deadline. Take a screenshot and look at it; to wait for it, act with no actions, and drag again only if the item did not move."},
		{"drags that started none", dragHint(&dragOut{Outcome: "partial", Private: true, Count: 6, Finished: 6, None: 2}, nil),
			"Not every drag of the batch went through: 6 finished, 2 drags started none. A drag that started no drag-and-drop moved nothing in an app that drags that way, as when it was not ready to start one. Take a screenshot and look at it, and drag again only the items that did not move."},
		{"drags unconfirmed and cancelled", dragHint(&dragOut{Outcome: "partial", Private: true, Count: 2, Unconfirmed: 1, Cancelled: 1, Reasons: []string{"rejected"}}, nil),
			"Not every drag of the batch went through: 1 cancelled (rejected), 1 unconfirmed. Nothing was dropped for a cancelled one. Take a screenshot and look at it, and drag again only the items that did not move; an unconfirmed or pending drop may have moved its item already."},
		{"paused for \"user_button\"", pausedError("fake input_paused", "user_button", false).Message,
			"fake input_paused: the user is holding a mouse button in a window of the same app, which the input would have released"},
		{"paused for \"user_button\", nothing delivered", pausedError("fake input_paused", "user_button", false).Hint,
			"The plugin held the input back for a second, then paused it. Retry once the user has let go, or ask the user."},
		{"paused for \"user_button\", some delivered", pausedError("fake input_paused", "user_button", true).Hint,
			"The plugin held the input back for a second, then paused it and dropped the rest. Go on once the user has let go, or ask the user."},
		{"paused for \"user_key\"", pausedError("fake input_paused", "user_key", false).Message,
			"fake input_paused: the user is holding a key in a window of the same app, which the input would have released"},
		{"paused for \"user_key\", nothing delivered", pausedError("fake input_paused", "user_key", false).Hint,
			"The plugin held the input back for a second, then paused it. Retry once the user has let go, or ask the user."},
		{"paused for \"user_key\", some delivered", pausedError("fake input_paused", "user_key", true).Hint,
			"The plugin held the input back for a second, then paused it and dropped the rest. Go on once the user has let go, or ask the user."},
		{"paused for \"x11_unresponsive\"", pausedError("fake input_paused", "x11_unresponsive", false).Message,
			"fake input_paused: the window's X server did not answer in time"},
		{"paused for \"x11_unresponsive\", nothing delivered", pausedError("fake input_paused", "x11_unresponsive", false).Hint,
			"The plugin paused the input for half a second. Retry; if it happens again, tell the user."},
		{"paused for \"x11_unresponsive\", some delivered", pausedError("fake input_paused", "x11_unresponsive", true).Hint,
			"The plugin paused the input for half a second and dropped the rest. Look at the window, then go on from what it shows."},
		{"paused for \"x11_focus\"", pausedError("fake input_paused", "x11_focus", false).Message,
			"fake input_paused: the user is working in another window of the same X server"},
		{"paused for \"x11_focus\", nothing delivered", pausedError("fake input_paused", "x11_focus", false).Hint,
			"Retry later, or ask the user."},
		{"paused for \"x11_focus\", some delivered", pausedError("fake input_paused", "x11_focus", true).Hint,
			"Go on once the user has left it, or ask the user."},
		{"paused for \"\"", pausedError("fake input_paused", "", false).Message,
			"fake input_paused: the user is working in another window of the same X server"},
		{"paused for \"\", nothing delivered", pausedError("fake input_paused", "", false).Hint,
			"Retry later, or ask the user."},
		{"paused for \"\", some delivered", pausedError("fake input_paused", "", true).Hint,
			"Go on once the user has left it, or ask the user."},
		{"closed after 0 delivered: message", closedWhileSent("0xa1", batch, 0, 0).Message,
			"window 0xa1 closed while actions[0] (key) was sent"},
		{"closed after 0 delivered: hint", closedWhileSent("0xa1", batch, 0, 0).Hint,
			"The window closed while the input was sent, maybe because of it, for example through a quit shortcut or a close button. Call windows to see what is open now."},
		{"closed after 1 delivered: message", closedWhileSent("0xa1", batch, 1, 1).Message,
			"window 0xa1 closed after actions[0] (key) was delivered, while actions[1] (pause) was sent"},
		{"closed after 1 delivered: hint", closedWhileSent("0xa1", batch, 1, 1).Hint,
			"The window closed after actions[0] (key) was delivered, maybe because of it, for example through a quit shortcut or a close button, so do not send it again. Call windows to see what is open now."},
		{"closed after 2 delivered: message", closedWhileSent("0xa1", batch, 2, 2).Message,
			"window 0xa1 closed after actions[0] (key) and actions[1] (pause) were delivered, while actions[2] (type) was sent"},
		{"closed after 2 delivered: hint", closedWhileSent("0xa1", batch, 2, 2).Hint,
			"The window closed after actions[0] (key) and actions[1] (pause) were delivered, maybe because of them, for example through a quit shortcut or a close button, so do not send them again. Call windows to see what is open now."},
		{"closed after 3 delivered: message", closedWhileSent("0xa1", batch, 3, 3).Message,
			"window 0xa1 closed after actions[0] to actions[2] were delivered, while actions[3] (click) was sent"},
		{"closed after 3 delivered: hint", closedWhileSent("0xa1", batch, 3, 3).Hint,
			"The window closed after actions[0] to actions[2] were delivered, maybe because of them, for example through a quit shortcut or a close button, so do not send them again. Call windows to see what is open now."},
		{"deadline, delivery none, defaultDeadline", asToolError(deadlineWhileSending("none", defaultDeadline)).Hint,
			"Retry, or give a larger deadline_ms (at most 30000)."},
		{"deadline, delivery partial, defaultDeadline", asToolError(deadlineWhileSending("partial", defaultDeadline)).Hint,
			"The deadline stopped the input part-way. Once you have seen how far it got, send the rest with a larger deadline_ms, or in parts over several calls."},
		{"deadline, delivery partial, maxDeadline", asToolError(deadlineWhileSending("partial", maxDeadline)).Hint,
			"The deadline stopped the input part-way. Once you have seen how far it got, send the rest in parts over several calls."},
		{"resizing shot", resizingHint(&shotOut{ID: "s3", Resizing: true}),
			"Shot s3 shows an older frame, since the window had not yet redrawn at its new size, so act takes no coordinates from it. To wait for the redraw, act with no actions and wait.expect_change false, and read the coordinates from the shot it returns; if the window does not redraw, use the keyboard or tell the user."},
		{"starved shot", starvedHint(&shotOut{ID: "s3", starved: &starvation{WaitedMs: 1000}}),
			"Shot s3 may show an older frame: the window is on a hidden workspace, where it gets no frame callbacks, which many applications wait for before they draw, and it did not redraw within 1000 ms of those this call sent it. If the shot looks complete, go on; if it looks empty or unfinished, as an application that is still starting does, wait: act with no actions, a larger wait.expect_ms and a deadline_ms at least 1000 above it, and use the shot it returns."},
		{"starved shot without time to wait", starvedHint(&shotOut{ID: "s3", starved: &starvation{}}),
			"Shot s3 may show an older frame: the window is on a hidden workspace, where it gets no frame callbacks, which many applications wait for before they draw, and this call had no time left to send it some. If the shot looks complete, go on; if it looks empty or unfinished, as an application that is still starting does, wait: act with no actions, a larger wait.expect_ms and a deadline_ms at least 1000 above it, and use the shot it returns."},
		{"closed", closedHint(nil),
			"The window closed. Any new windows are listed; call windows for the rest."},
		{"closed, back to its source", closedHint(&sourceOut{Window: "0xa1"}),
			"The window closed. It came from window 0xa1: take a screenshot of it to go on there. Any new windows are listed; call windows for the rest."},
		{"closed, back to its source's shot", closedHint(&sourceOut{Window: "0xa1", Shot: &shotOut{ID: "s9"}}),
			"The window closed. It came from window 0xa1, which shot s9 shows now: go on there with that shot's pixels. Any new windows are listed; call windows for the rest."},
		{"opened windows", openedHint([]newWindowOut{{Window: "0xd2", Title: "Helper", Workspace: "1", Visible: true, Focused: true, fromTarget: true, Shot: &shotOut{ID: "s3"}}, {Window: "0xd5", Title: "Odd", Workspace: "1", Visible: true, NotPlaced: "workspace", fromTarget: true, Shot: &shotOut{ID: "s4"}}}),
			"The input opened new windows 0xd2 \"Helper\" in shot s3, 0xd5 \"Odd\" in shot s4."},
		{"new windows on the user's workspace", newWindowsHint([]newWindowOut{{Window: "0xd2", Title: "Helper", Workspace: "1", Visible: true, Focused: true, fromTarget: true, Shot: &shotOut{ID: "s3"}}, {Window: "0xd5", Title: "Odd", Workspace: "1", Visible: true, NotPlaced: "workspace", fromTarget: true, Shot: &shotOut{ID: "s4"}}}),
			"New window 0xd2 opened on the user's visible workspace 1 and has their keyboard focus, so what they type goes there, since the plugin could not tell that hyprmasq's input opened it. Tell the user. New window 0xd5 opened on the user's visible workspace 1, since no window rule can name the workspace of the window it came from. Tell the user."},
		{"no change", noChangeHint(delivered(unchangedShot("s1")), click),
			"Nothing changed since s1, so the input may have missed or had no visible effect; it may also have opened a window that maps later, as a file chooser of another process can a second or two after the input: windows with wait_ms waits for it, and your next act or screenshot returns it. Look at s1 before repeating it."},
		{"only tiny changes", noChangeHint(delivered(&shotOut{ID: "s2", Changes: &changesOut{Base: "s1", LeftOut: 1}}), []action{{Kind: "type"}}),
			"Only tiny changes since s1, such as a caret that moved or blinked, so the input may have missed or had little visible effect. Look at s1 before repeating it."},
		{"no change outside animations", noChangeHint(delivered(&shotOut{ID: "s2", Changes: &changesOut{Base: "s1", Animated: 3}}), []action{{Kind: "type"}}),
			"Nothing changed since s1 outside the animations, so the input may have missed, or its effect lies inside them. Look at s1, or take a screenshot to see the animations as they are now, before repeating it."},
		{"no change outside animations after keys", noChangeHint(delivered(&shotOut{ID: "s2", Changes: &changesOut{Base: "s1", Animated: 3}}), []action{{Kind: "key"}}),
			"Nothing changed since s1 outside the animations, so the input may have missed, or its effect lies inside them" + laterWindow(click) + ". Look at s1, or take a screenshot to see the animations as they are now, before repeating it."},
		{"a window that maps later", laterWindow(click),
			"; it may also have opened a window that maps later, as a file chooser of another process can a second or two after the input: windows with wait_ms waits for it, and your next act or screenshot returns it"},
		{"late window", lateHint([]newWindowOut{{Window: "0xf4", Title: "Report f4", Source: "0xa1", Shot: &shotOut{ID: "s5"}}}),
			"Your input to 0xa1 in an earlier act opened window 0xf4 \"Report f4\" after that act had returned; it is in shot s5."},
		{"no redraw during the call", waitHint(&waitOut{Ended: "no_redraw"}, nil, "", &actionsOut{}, nil),
			"Nothing was drawn during this call. If the window is still loading, wait again: act with no actions, a larger wait.expect_ms, and a deadline_ms at least 1000 above it."},
		{"no redraw after keys", waitHint(&waitOut{Ended: "no_redraw"}, []action{{Kind: "key"}}, "", &actionsOut{Done: 1, Total: 1, Delivery: "complete"}, nil),
			"The keys may have gone to another widget or had no visible effect; it may also have opened a window that maps later, as a file chooser of another process can a second or two after the input: windows with wait_ms waits for it, and your next act or screenshot returns it. Take a screenshot and look at it before repeating them."},
		{"no change after a scroll", noChangeHint(delivered(unchangedShot("s1")), []action{{Kind: "scroll"}}),
			"Nothing moved since s1: the page may be at its end, or nothing under the pointer scrolls."},
		{"part of the window scrolled", partScrolledHint(delivered(&shotOut{ID: "s2", Changes: &changesOut{Base: "s1", Regions: []regionOut{{Shot: "s3"}}}}), []action{{Kind: "scroll"}}),
			"The scroll changed only part of the window: a list there scrolled, or a control under the pointer, such as a dropdown, took the wheel and changed its value. Look at the zooms, and scroll over the page's background to move the page."},
		{"scroll held back", heldBackHint(&actionsOut{HeldBack: "the actions before it drew nothing, so they may have missed"}),
			"The scroll was not sent: the actions before it drew nothing, so they may have missed. The page has not moved: look at the result, and scroll in an act of its own if you still want to."},
		{"scroll after zooms", splitHint(&actOut{BeforeScroll: &beforeScrollOut{Shot: &shotOut{ID: "s2", Changes: &changesOut{Base: "s1", Regions: []regionOut{{Shot: "s3"}}}}}, Shot: &shotOut{ID: "s4"}}),
			"The zooms of s2 show what the actions before the scroll changed. Shot s4 shows the window after the scroll: read the next coordinates from s4."},
		{"scroll after a full shot", splitHint(&actOut{BeforeScroll: &beforeScrollOut{Shot: &shotOut{ID: "s2"}}, Shot: &shotOut{ID: "s3"}}),
			"Shot s2 shows the window after the actions before the scroll. Shot s3 shows the window after the scroll: read the next coordinates from s3."},
		{"scroll after no change", splitHint(&actOut{BeforeScroll: &beforeScrollOut{Shot: unchangedShot("s1")}, Shot: &shotOut{ID: "s3"}}),
			"The actions before the scroll changed nothing visible since s1. Shot s3 shows the window after the scroll: read the next coordinates from s3."},
		{"close of an X11 menu: message", x11CloseRefusal("0xb2", menuState, appWindows).Message,
			"window 0xb2 is a menu, list or tooltip of an X11 app, which only the app can close: closing it through Hyprland ends or breaks the whole app"},
		{"close of an X11 menu: hint", x11CloseRefusal("0xb2", menuState, appWindows).Hint,
			"To dismiss it, act on window 0xb2 with the key escape, or click in window 0xa1 outside it. To pick an item, click it."},
		{"close of an X11 menu of an unknown window: hint", x11CloseRefusal("0xb2", menuState, nil).Hint,
			"To dismiss it, act on window 0xb2 with the key escape, or click in the app's window outside it. To pick an item, click it."},
		{"close of an X11 window without WM_DELETE_WINDOW: message", x11CloseRefusal("0xc3", hypr.State{X11: &hypr.X11Kind{}}, nil).Message,
			"X11 window 0xc3 takes no close request (WM_DELETE_WINDOW), so Hyprland can only close it by ending its app with all of its windows"},
		{"close of an X11 window without WM_DELETE_WINDOW: hint", x11CloseRefusal("0xc3", hypr.State{X11: &hypr.X11Kind{}}, nil).Hint,
			"Quit the app from within it, such as through its menu or a shortcut like ctrl+q, or ask the user to close it."},
		{"close of an X11 window that the plugin does not describe: message", x11CloseRefusal("0xd4", hypr.State{}, nil).Message,
			"the hyprmasq plugin does not tell whether Hyprland can close X11 window 0xd4 without ending or breaking its app"},
		{"close of an X11 window that the plugin does not describe: hint", x11CloseRefusal("0xd4", hypr.State{}, nil).Hint,
			"Quit the app from within it, such as through its menu or a shortcut like ctrl+q, or ask the user to close it. The plugin loaded in Hyprland may be older than hyprmasq-mcp."},
	} {
		if c.got != c.want {
			t.Errorf("%s:\n got %q\nwant %q", c.name, c.got, c.want)
		}
	}
}
